<h1>Shipment Tracker</h1>
<p>Welcome to the logistics shipment tracking system.</p>

<div class="row">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Dispatcher Dashboard</h5>
                <p class="card-text">View and manage all shipments, update statuses.</p>
                <a href="/dispatch" class="btn btn-primary">Go to Dashboard</a>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <p class="card-text">Enter your tracking number to check status.</p>
                <a href="/track" class="btn btn-secondary">Track Shipment</a>
            </div>
        </div>
    </div>
</div>
```

Create `ShipmentTracker.Client/Pages/Dispatch.razor`:
```razor
@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

@if (_loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (_shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..."
